def is_symmetric(grid, axis='vertical'):
    """Check for horizontal/vertical symmetry in non-zero pattern"""
    if axis == 'vertical':
        n, m = len(grid), len(grid[0])
        # Check if pattern is symmetric around middle column
        for r in range(n):
            for c in range(m // 2):
                if grid[r][c] != 0 and grid[r][c] != grid[r][m - 1 - c]:
                    return False
                if grid[r][c] == 0 and grid[r][m - 1 - c] != 0:
                    return False
    elif axis == 'horizontal':
